// Planner → the Automations stage body, AS GRAPH SOURCE (#4230, epic #3604). Transcribed from the live feature file. Its
// `provides: "@/features/planner/bodies/FocusedAutomationsBody"` makes the runtime loader vendor THIS source wherever a graph
// component imports that specifier — so the stage-body switch reaches it from the graph without
// knowing it, and the registered module stays as the fallback. Behaviour runs here.
// Automations stage body (split from FocusedBodies.tsx #1757).
import type { PaneAutomation } from "@/features/planner/pane/projectPaneData";
import { ListItemCard } from "@/features/planner/bodies/bodyPrimitives";
import { Stack } from "@/shared/ui/layout/Stack";
import { EmptyState } from "@/shared/ui/feedback/EmptyState";

export function AutomationsBody({ automations }: { automations?: PaneAutomation[] }) {
  const list = automations ?? [];
  if (list.length === 0) {
    return <EmptyState iconVariant="dashed" icon="⏱" title="No automations yet" />;
  }
  return (
    <Stack gap={5}>
      {list.map((a) => (
        <ListItemCard
          key={a.name}
          title={a.name}
          meta={`${a.command}${a.schedule ? ` · ${a.schedule}` : ""}`}
        />
      ))}
    </Stack>
  );
}
